CREATE TABLE prompt_versions (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, purpose text NOT NULL, version integer NOT NULL, system_prompt text NOT NULL, schema_json jsonb NOT NULL DEFAULT '{}'::jsonb, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,purpose,version));
CREATE TABLE ai_runs (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, purpose text NOT NULL, provider text NOT NULL, model text NOT NULL, prompt_version_id uuid REFERENCES prompt_versions(id), input_refs jsonb NOT NULL, usage_json jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL CHECK(status IN ('running','succeeded','failed')), error_code text, created_by uuid REFERENCES users(id) ON DELETE SET NULL, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX ai_runs_workspace_started_idx ON ai_runs(workspace_id,started_at DESC);
CREATE TABLE ai_suggestions (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, run_id uuid NOT NULL REFERENCES ai_runs(id) ON DELETE CASCADE, target_object_id uuid NOT NULL, kind text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','rejected')), reviewed_by uuid REFERENCES users(id) ON DELETE SET NULL, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,target_object_id) REFERENCES objects(workspace_id,id) ON DELETE CASCADE);
CREATE INDEX ai_suggestions_pending_idx ON ai_suggestions(workspace_id,state,created_at DESC);
